#include "opencv2/dnn_superres.hpp"
#include "opencv2/dnn/all_layers.hpp"
#include "opencv2/imgproc.hpp"
#include <iostream>

using namespace cv;
using namespace cv::dnn;
using namespace cv::dnn_superres;

int main()
{
    Net net;
    LayerParams rp;
    rp.type = "Resize"; rp.name = "up";
    rp.set("zoom_factor", 2.f);
    rp.set("interpolation", String("bilinear"));
    net.addLayerToPrev(rp.name, rp.type, rp);

    LayerParams cp;
    cp.type = "Convolution"; cp.name = "conv";
    cp.set("kernel_size", 1);
    cp.set("num_output", 3);
    cp.set("bias_term", false);
    std::vector<int> ws = {3,3,1,1};
    Mat w(ws, CV_32F, Scalar(0));
    for (int c=0;c<3;++c) w.ptr<float>(c,c)[0] = 1.f/255.f;
    cp.blobs.push_back(w);
    net.addLayerToPrev(cp.name, cp.type, cp);
    net.setPreferableBackend(DNN_BACKEND_OPENCV);

    Mat img(2,2,CV_8UC3);
    img.setTo(Scalar(10,20,30));
    Mat blob = blobFromImages({img}, 1.0/255.0, Size(), Scalar(), false, false, CV_32F);
    std::cout << "blob size: " << blob.size[0] << "," << blob.size[1] << "," << blob.size[2] << "," << blob.size[3] << "\n";
    net.setInput(blob);
    Mat out = net.forward();
    std::cout << "out size: " << out.dims << " " << out.size[0] << "," << out.size[1] << "," << out.size[2] << "," << out.size[3] << "\n";
    std::cout << "out[0,0,0,0..2] = " << out.ptr<float>(0,0,0)[0] << " " << out.ptr<float>(0,1,0)[0] << " " << out.ptr<float>(0,2,0)[0] << "\n";

    Ptr<DnnSuperRes> sr = DnnSuperRes::create();
    sr->getNet() = net;
    sr->setPreprocessing(1.0/255.0, Scalar(), false);
    Mat res;
    sr->upsample(img, res);
    std::cout << "res size: " << res.size() << " type: " << res.type() << "\n";
    std::cout << "res px: " << res.at<Vec3b>(0,0) << "\n";
    return 0;
}

