#include "opencv2/dnn_superres.hpp"
#include "opencv2/dnn/all_layers.hpp"
#include "opencv2/imgproc.hpp"
#include "opencv2/imgcodecs.hpp"
#include <iostream>

using namespace cv;
using namespace cv::dnn;
using namespace cv::dnn_superres;

static Net toyNet(int factor)
{
    Net net;
    LayerParams rp;
    rp.type = "Resize"; rp.name = "up";
    rp.set("zoom_factor_x", (float)factor);
    rp.set("zoom_factor_y", (float)factor);
    rp.set("interpolation", String("bilinear"));
    rp.set("half_pixel_centers", true);
    net.addLayerToPrev(rp.name, rp.type, rp);
    LayerParams cp;
    cp.type = "Convolution"; cp.name = "conv";
    cp.set("kernel_size", 1); cp.set("num_output", 3); cp.set("bias_term", false);
    std::vector<int> ws = {3, 3, 1, 1};
    Mat w(ws, CV_32F, Scalar(0));
    for (int c = 0; c < 3; ++c) w.ptr<float>(c, c)[0] = 1.f;
    cp.blobs.push_back(w);
    net.addLayerToPrev(cp.name, cp.type, cp);
    return net;
}

int main()
{
    Ptr<DnnSuperRes> sr = DnnSuperRes::create();
    sr->getNet() = toyNet(2);
    sr->setScale(2);
    sr->setPreprocessing(1.0 / 255.0, Scalar(), false);

    Mat img(12, 16, CV_8UC3);
    randu(img, Scalar::all(0), Scalar::all(255));

    Mat single;
    sr->upsample(img, single);
    std::cout << "single: " << single.size() << " type=" << single.type() << "\n";

    std::vector<Mat> batch = {img, img, img};
    std::vector<Mat> out;
    sr->upsampleMulti(batch, out, 2);
    std::cout << "batch chunks: " << out.size() << " first=" << out[0].size() << "\n";

    sr->upsampleMultiInplace(batch);
    std::cout << "inplace: " << batch.size() << " " << batch[0].size() << "\n";

    imwrite("/tmp/debugclean/out.png", out[0]);
    std::cout << "algo=" << sr->getAlgorithm() << " scale=" << sr->getScale()
              << " loaded=" << sr->isLoaded() << "\n";
    return 0;
}

